CREATE COLUMN TABLE "TEST_AP"."AWO4" ("DocEntry" INTEGER CS_INT NOT NULL , "StageId" INTEGER CS_INT NOT NULL , "SeqNum" INTEGER CS_INT NOT NULL , "StgEntry" INTEGER CS_INT, "Name" NVARCHAR(100), "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "StartDate" LONGDATE CS_LONGDATE, "EndDate" LONGDATE CS_LONGDATE, "Status" NVARCHAR(1) DEFAULT 'O', "RtCalcProp" DECIMAL(21,6) CS_FIXED DEFAULT 100, "ReqDays" DECIMAL(21,6) CS_FIXED DEFAULT 0, "WaitDays" DECIMAL(21,6) CS_FIXED DEFAULT 0, PRIMARY KEY ("DocEntry", "StageId", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "AWO4_SEQUENCE" ON "TEST_AP"."AWO4" ( "DocEntry" ASC, "SeqNum" ASC, "LogInstanc" ASC )